// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Delete(options.BaseURL+"/session", wrapper.DeleteSession)

	router.Get(options.BaseURL+"/session", wrapper.GetSession)

	router.Post(options.BaseURL+"/session", wrapper.CreateSession)

	router.Delete(options.BaseURL+"/session/reference", wrapper.DetachReference)

	router.Get(options.BaseURL+"/session/reference", wrapper.GetReference)

	router.Post(options.BaseURL+"/session/reference", wrapper.AttachReference)

	router.Get(options.BaseURL+"/tree", wrapper.ListChildren)

	router.Get(options.BaseURL+"/count", wrapper.CountEntries)

	router.Get(options.BaseURL+"/compare", wrapper.CompareEntries)

	router.Get(options.BaseURL+"/entry", wrapper.GetEntry)

	router.Post(options.BaseURL+"/search", wrapper.Search)

	router.Get(options.BaseURL+"/views", wrapper.ListObjectViews)

	router.Post(options.BaseURL+"/inventory", wrapper.InventoryValues)

	router.Get(options.BaseURL+"/members", wrapper.ExpandMembers)

	router.Get(options.BaseURL+"/references", wrapper.ListReferences)

	router.Get(options.BaseURL+"/resolve", wrapper.Resolve)

	router.Get(options.BaseURL+"/schema", wrapper.GetSchema)

	router.Get(options.BaseURL+"/schema/objectclasses/:name", wrapper.GetObjectClass)

	router.Get(options.BaseURL+"/schema/attributetypes/:name", wrapper.GetAttributeType)

	router.Get(options.BaseURL+"/schema/requirements", wrapper.GetRequirements)

	router.Post(options.BaseURL+"/schema/change", wrapper.BuildSchemaChange)

	router.Post(options.BaseURL+"/changes/preview", wrapper.PreviewChange)

	router.Post(options.BaseURL+"/changes/apply", wrapper.ApplyChange)

	router.Post(options.BaseURL+"/changes/outcome", wrapper.DetermineChangeOutcome)

	router.Post(options.BaseURL+"/changeset/preview", wrapper.PreviewChangeset)

	router.Post(options.BaseURL+"/changeset/apply", wrapper.ApplyChangeset)

	router.Post(options.BaseURL+"/recovery/inspect", wrapper.InspectRecovery)

	router.Post(options.BaseURL+"/plan", wrapper.PlanChanges)

	router.Post(options.BaseURL+"/project/plan", wrapper.PlanProject)

	router.Get(options.BaseURL+"/access", wrapper.GetAccessRules)

	router.Get(options.BaseURL+"/policy", wrapper.GetPasswordPolicy)

	router.Get(options.BaseURL+"/replication", wrapper.GetReplication)

	router.Get(options.BaseURL+"/replication/entry", wrapper.GetEntryReplication)

	router.Get(options.BaseURL+"/replication/conflicts", wrapper.GetReplicationConflicts)

	router.Get(options.BaseURL+"/config/entry", wrapper.GetConfigEntryModel)

	router.Get(options.BaseURL+"/config/indexes", wrapper.GetConfigIndexes)

	router.Post(options.BaseURL+"/config/indexes/candidate", wrapper.PlanConfigIndex)

	router.Post(options.BaseURL+"/snapshots/capture", wrapper.CaptureSnapshot)

	router.Post(options.BaseURL+"/snapshots/capture/from", wrapper.CaptureFromAnotherServer)

	router.Post(options.BaseURL+"/snapshots/inspect", wrapper.InspectSnapshot)

	router.Post(options.BaseURL+"/diff", wrapper.DiffStates)

	router.Post(options.BaseURL+"/packages/build", wrapper.BuildPackage)

	router.Post(options.BaseURL+"/packages/inspect", wrapper.InspectPackage)

	router.Post(options.BaseURL+"/packages/validate", wrapper.ValidatePackage)

	router.Post(options.BaseURL+"/preflight", wrapper.Preflight)

	router.Get(options.BaseURL+"/export/ldif", wrapper.ExportLdif)

	router.Get(options.BaseURL+"/export/ansible", wrapper.ExportAnsible)

	router.Get(options.BaseURL+"/export/outline", wrapper.ExportOutline)

	router.Get(options.BaseURL+"/export/yaml", wrapper.ExportYaml)

	router.Post(options.BaseURL+"/import/ldif", wrapper.ParseLdif)

	router.Get(options.BaseURL+"/source", wrapper.GetSourceOffer)

}

